import{_ as a,o as e,c as d,b6 as i}from"./chunks/framework.CNUu10b_.js";const p=JSON.parse('{"title":"Alex 的产品发布学习路线","description":"为已经能用 AI 做出原型、但希望把作品真正发布出去的人设计的 Easy-Vibe 学习路线。","frontmatter":{"title":"Alex 的产品发布学习路线","description":"为已经能用 AI 做出原型、但希望把作品真正发布出去的人设计的 Easy-Vibe 学习路线。"},"headers":[],"relativePath":"zh-cn/personal-roadmap/index.md","filePath":"zh-cn/personal-roadmap/index.md"}'),r={name:"zh-cn/personal-roadmap/index.md"};function l(n,t,h,s,o,b){return e(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="alex-的产品发布学习路线" tabindex="-1">Alex 的产品发布学习路线 <a class="header-anchor" href="#alex-的产品发布学习路线" aria-label="Permalink to “Alex 的产品发布学习路线”">​</a></h1><p>你现在最需要的不是再学一遍“如何开始用 AI 写代码”，而是把已经做出来的一批原型，筛选、打磨、上线，并让陌生用户愿意打开、理解、试用和传播。</p><p>从教育设计角度看，最适合你的学习方式不是从头刷完 Easy-Vibe，而是采用“真实项目驱动”的路线：每看一节课，就立刻把它应用到你手里的一个产品上。学习的证据不是“看完了”，而是产出了一个能发布、能展示、能复盘的具体物件。</p><h2 id="教育视角评估" tabindex="-1">教育视角评估 <a class="header-anchor" href="#教育视角评估" aria-label="Permalink to “教育视角评估”">​</a></h2><p>我重新审查后，认为这套路线整体适合你，但原版路线还需要补强三点：</p><ol><li><strong>先筛选项目，再补技术。</strong> 你不是缺少想法，而是缺少判断哪个半成品值得进入发布流程的标准，所以需要把 JTBD、用户访谈、需求验证提前。</li><li><strong>把“看课”改成“交付证据”。</strong> 每节推荐课都应该对应一个产出，比如一句话定位、核心流程图、可访问链接、反馈入口、发布短文、数据看板。</li><li><strong>把发布后的增长闭环补上。</strong> 你想吸引流量和注意力，所以路线不能停在部署成功，还要覆盖技术写作、作品展示、数据埋点、开源协作和持续迭代。</li></ol><p>因此，这页优化后的目标是：帮你从“会做 AI 玩具的人”，过渡到“能持续发布小产品、沉淀作品集、建立个人名气的人”。</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h2><p>优先级分成三类：</p><ul><li><strong>必学</strong>：直接对应你目前最大的卡点，建议先看。</li><li><strong>选学</strong>：根据当前项目类型选择，没用到时可以跳过。</li><li><strong>加分</strong>：能提高专业感、传播力或长期维护能力，但不用阻塞第一次发布。</li></ul><p>学习时建议只选一个真实项目作为练习对象。不要同时救十个半成品，先把一个项目推到公网，再把方法复用到下一个。</p><h2 id="路线总览" tabindex="-1">路线总览 <a class="header-anchor" href="#路线总览" aria-label="Permalink to “路线总览”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>教育目标</th><th>你的阶段产出</th></tr></thead><tbody><tr><td>0. 项目筛选</td><td>从一堆半成品里挑出最值得发布的一个</td><td>1 个候选项目评分表和 1 个清晰定位</td></tr><tr><td>1. 产品化</td><td>把玩具变成陌生人能理解的小产品</td><td>核心流程、落地页、可试用 MVP</td></tr><tr><td>2. 工程化</td><td>补齐上线、数据、稳定性和维护能力</td><td>公网链接、数据存储、反馈入口、发布检查表</td></tr><tr><td>3. 发布与增长</td><td>让作品被看见，并根据反馈迭代</td><td>发布短文、演示视频、数据复盘、下一版计划</td></tr><tr><td>4. 作品集与品牌</td><td>把多个产品变成个人品牌资产</td><td>个人主页、项目目录、代表作展示</td></tr></tbody></table><h2 id="_0-先筛选-哪个项目值得你投入发布" tabindex="-1">0. 先筛选：哪个项目值得你投入发布？ <a class="header-anchor" href="#_0-先筛选-哪个项目值得你投入发布" aria-label="Permalink to “0. 先筛选：哪个项目值得你投入发布？”">​</a></h2><p>目标：避免你继续在一堆“有趣但不成产品”的原型之间切换。先选一个最值得发布的项目，给它明确边界。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/finding-great-idea/">找到好点子</a></td><td>判断需求是否真实，区分痛点、爽点和痒点，把模糊 idea 改成更窄、更有购买或使用动机的产品方向。</td><td>从你的半成品里选出 1 个最适合发布的项目，并写出“谁在什么场景下为什么需要它”。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/appendix-jobs-to-be-done/">用 Jobs to Be Done 找到用户真正想完成的事</a></td><td>用“用户想完成的进展”替代功能堆叠，避免产品只是在展示技术。</td><td>1 条 JTBD 句子、3 个目标场景、3 个用户成功标准。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/appendix-mom-test/">The Mom Test：如何通过用户访谈验证需求</a></td><td>学会问过去事实、替代方案和真实成本，避免被“这个挺好我会用”误导。</td><td>5 个访谈问题、3 位潜在用户名单、一次访谈记录模板。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-1/appendix-double-diamond/">双钻模型：先做对的事，再把事做对</a></td><td>在发散和收敛之间切换，把“想加更多功能”变成“先定义最关键的问题”。</td><td>一个不做清单：本版本明确不做哪些功能。</td></tr></tbody></table><p>阶段通过标准：</p><ul><li>你能用一句话说清楚项目服务谁。</li><li>你知道用户现在不用你的产品时，用什么替代方案。</li><li>你能指出这个项目为什么值得发布，而不是只因为它已经做了一半。</li></ul><h2 id="_1-从小玩具到可发布小产品" tabindex="-1">1. 从小玩具到可发布小产品 <a class="header-anchor" href="#_1-从小玩具到可发布小产品" aria-label="Permalink to “1. 从小玩具到可发布小产品”">​</a></h2><p>目标：把“我做了个好玩的东西”变成“陌生用户能打开、理解、完成核心流程，并愿意给反馈”的小产品。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/learning-map/">学习地图</a></td><td>了解 Easy-Vibe 的整体学习结构，知道哪些内容是起步、哪些是产品化、哪些是进阶能力。</td><td>给自己标记一条 2 到 4 周的学习路径，避免到处补课。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/building-prototype/">搭建产品原型</a></td><td>从业务问题拆出页面、流程和核心功能，把功能堆叠改成用户能走通的主路径。</td><td>一张核心用户流程图，以及一个能完成主任务的 MVP。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/complete-project-practice/">完整项目实战</a></td><td>补齐等待、错误、反馈、模拟数据和迭代这些“像产品”的细节。</td><td>一个更完整的可试用版本，包含空状态、加载状态、错误状态和基础反馈。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-1/integrating-ai-capabilities/">接入 AI 能力</a></td><td>把文本生成、图像理解或图像生成接进产品流程，并理解 API、Key、调用和错误处理。</td><td>产品中至少有一个稳定可解释的 AI 能力，而不是只做一次性 demo。</td></tr><tr><td>加分</td><td><a href="/easy-vibe/zh-cn/stage-1/introduction-to-ai-ide/">初级：学会 AI 编程工具</a></td><td>系统熟悉 AI IDE 的使用方式，减少靠运气生成代码。</td><td>一套你自己的 AI 编程提示词和修复流程。</td></tr></tbody></table><p>这一阶段的完成标准：</p><ul><li>首页 5 秒内能让陌生人明白价值。</li><li>用户不用问你，也能完成一次核心流程。</li><li>产品不是“功能展示页”，而是围绕一个明确任务组织。</li><li>你知道第一批该找哪 5 到 20 个用户试用。</li></ul><h2 id="_2-从小产品到完整产品" tabindex="-1">2. 从小产品到完整产品 <a class="header-anchor" href="#_2-从小产品到完整产品" aria-label="Permalink to “2. 从小产品到完整产品”">​</a></h2><p>目标：补齐真实产品需要的工程底座，包括界面、数据、接口、部署、版本管理、支付和质量检查。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/backend/zeabur-deployment/">网页应用部署全面指南</a></td><td>理解部署是什么，如何把项目放到公网，以及 Vercel、Netlify、Zeabur 等平台的基本差异。</td><td>一个任何人都能打开的公网链接。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/backend/git-workflow/">Git 与 GitHub 入门指南</a></td><td>掌握 clone、commit、push、pull、SSH 和 GitHub 仓库发布的基本流程。</td><td>一个公开或私有 GitHub 仓库，以及一次可回溯的发布记录。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/frontend/llm-skills-beautiful/">结合 Agent Skills 美化界面</a></td><td>学会用设计提示词和 Skills 改善 AI 默认生成界面的廉价感。</td><td>产品首页或主界面完成一次视觉重做。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/frontend/modern-component-library/">现代组件库与界面升级</a></td><td>理解组件库如何提升一致性、可维护性和专业感。</td><td>统一的按钮、表单、导航、卡片、弹窗或仪表盘组件。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/backend/database-supabase/">数据库与 Supabase 入门</a></td><td>从“刷新就没了”的本地状态，进入用户、数据、权限和持久化。</td><td>至少一张真实数据表，以及一个能读写数据的核心功能。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/backend/ai-interface-code/">大模型辅助接口开发</a></td><td>理解前后端如何通过 API 连接，如何让 AI 辅助写接口、文档和测试。</td><td>一个清楚的 API 设计，或者至少一个稳定的前后端连接点。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-2/backend/stripe-payment/">Stripe 支付集成</a></td><td>了解收费系统、支付流程、订单状态和 webhook 的基本逻辑。</td><td>如果项目适合商业化，产出一个测试支付流程。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/backend/modern-cli/">CLI Coding Agent 编程助手</a></td><td>用命令行 Agent 做更稳定的修复、重构、测试和发布前检查。</td><td>一份发布前检查流程：构建、测试、代码检查、手动验收。</td></tr></tbody></table><p>发布检查清单：</p><ul><li>有公开访问链接。</li><li>有清楚的登录或免登录体验路径。</li><li>有空状态、加载状态、错误状态。</li><li>有基础数据存储，不依赖浏览器刷新后“全没了”。</li><li>有反馈入口，例如邮箱、表单、GitHub issue、微信群或飞书表单。</li><li>有一个最小指标：访问量、注册数、使用次数、生成次数或留存。</li></ul><h2 id="_3-发布后的优化、数据与增长" tabindex="-1">3. 发布后的优化、数据与增长 <a class="header-anchor" href="#_3-发布后的优化、数据与增长" aria-label="Permalink to “3. 发布后的优化、数据与增长”">​</a></h2><p>目标：不是发布一次就结束，而是知道用户从哪里来、在哪里卡住、下一版该改什么，并把发布变成个人影响力资产。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/appendix/5-data/data-tracking.html">数据埋点</a></td><td>记录用户访问、点击、生成、提交、退出等关键行为。</td><td>3 到 5 个关键事件，例如访问首页、点击开始、完成生成、提交反馈。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/appendix/5-data/data-analysis.html">数据分析</a></td><td>用漏斗、留存、转化和分群理解产品是否真的变好。</td><td>一份发布后复盘：流量、完成率、反馈、下一步优先级。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/appendix/5-data/ab-testing.html">A/B 测试</a></td><td>当你开始优化标题、按钮、定价和落地页时，学会用实验判断方案。</td><td>一个小实验计划，例如两个标题或两个 CTA 的对比。</td></tr><tr><td>加分</td><td><a href="/easy-vibe/zh-cn/appendix/5-data/data-visualization.html">数据可视化</a></td><td>把零散数据整理成能长期查看的仪表盘。</td><td>一个产品数据看板，哪怕最开始只用表格。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/appendix/9-engineering-excellence/technical-writing.html">技术写作</a></td><td>用 README、发布说明和文章讲清楚作品价值，降低陌生人理解成本。</td><td>一篇 500 到 1000 字的发布短文。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/appendix/9-engineering-excellence/open-source-collaboration.html">开源协作</a></td><td>理解 README、issue、license、贡献说明和 GitHub 展示方式。</td><td>一个更像正式项目的 GitHub 首页。</td></tr><tr><td>加分</td><td><a href="/easy-vibe/zh-cn/appendix/3-browser-and-frontend/web-performance.html">Web 性能优化</a></td><td>理解加载速度、资源体积和核心体验指标对传播转化的影响。</td><td>一轮性能检查和 2 到 3 个具体优化。</td></tr></tbody></table><p>建议你每个发布项目都配一篇短文，结构固定为：</p><ol><li>我遇到或观察到什么问题。</li><li>我做了什么产品来解决它。</li><li>你可以在哪里试用。</li><li>它现在还不完美，下一步会改什么。</li></ol><h2 id="_4-ai-agent-与自动化产品方向" tabindex="-1">4. AI Agent 与自动化产品方向 <a class="header-anchor" href="#_4-ai-agent-与自动化产品方向" aria-label="Permalink to “4. AI Agent 与自动化产品方向”">​</a></h2><p>目标：把你已经会做的 AI demo 升级成更稳定、更可复用的 Agent、知识库或工作流产品。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-3/core-skills/workflow/">AI 辅助开发工作流</a></td><td>学会用 AI 分阶段做新功能、修 Bug、重构、审查和项目知识库沉淀。</td><td>为一个项目建立 <code>README</code>、开发流程、常见问题和任务模板。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-3/core-skills/spec-coding/">从 Vibe Coding 到 Spec Coding</a></td><td>把随手做功能变成有规格、有计划、有验收标准的开发。</td><td>为你的当前产品写一份轻量 PRD、任务拆解和验收标准。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/ai-capabilities/dify-knowledge-base/">Dify 入门与知识库集成</a></td><td>用工作流平台搭建可配置的 AI 应用和知识库问答。</td><td>一个可演示的知识库或流程型 AI 应用。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-3/ai-advanced/rag-introduction/">RAG 入门</a></td><td>理解检索增强生成的基本流程：切分、向量化、检索、回答和评估。</td><td>一个基于资料回答问题的原型。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-3/ai-advanced/langgraph-advanced-rag/">LangGraph 高级 RAG</a></td><td>学会更复杂的多步骤 Agent 流程、状态管理和可审计设计。</td><td>一个多步骤客服、研究或资料处理 Agent 的设计稿。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-3/core-skills/mcp/">MCP 与 Claude Code 完整指南</a></td><td>让 AI 连接工具、服务和外部系统，形成更有生产力的自动化。</td><td>一个能连接外部工具或本地资源的 AI 工作流。</td></tr><tr><td>加分</td><td><a href="/easy-vibe/zh-cn/stage-3/core-skills/skills/">Claude Code Skills 完整指南</a></td><td>把重复开发流程沉淀成可复用技能。</td><td>一个服务你自己产品开发的 personal skill。</td></tr><tr><td>加分</td><td><a href="/easy-vibe/zh-cn/stage-3/core-skills/long-running-tasks/">让 Claude Code 胜任长任务</a></td><td>管理长任务、上下文、分步执行和复杂项目推进。</td><td>一套适合多天迭代的任务推进文档。</td></tr></tbody></table><p>这组课程特别适合你“第二次重做”某个项目时使用：先别急着继续加功能，先把需求、流程、工具和验收标准写清楚。</p><h2 id="_5-个人品牌与作品展示" tabindex="-1">5. 个人品牌与作品展示 <a class="header-anchor" href="#_5-个人品牌与作品展示" aria-label="Permalink to “5. 个人品牌与作品展示”">​</a></h2><p>目标：让别人能看见你、记住你，并通过你的作品理解你的能力。这一组直接服务于你“提升名气、吸引流量和注意力”的目标。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-3/personal-brand/personal-website-blog/">如何构建个人网页与学术博客</a></td><td>用 GitHub Pages 等方式建立长期作品橱窗，展示项目、文章和个人介绍。</td><td>一个可公开访问的个人主页或项目主页。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-3/cross-platform/choose-platform/">选择合适的平台</a></td><td>判断产品应该做网页、插件、PWA、桌面端、小程序还是移动端。</td><td>为你的 3 个候选项目各选一个最合适的发布形态。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-3/cross-platform/browser-ai-extension/">浏览器 AI 助手插件</a></td><td>开发更容易传播的浏览器插件类 AI 产品。</td><td>一个能在浏览器里使用的小插件原型。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-3/cross-platform/vscode-extension/">VS Code 插件</a></td><td>面向开发者用户做工具型作品，适合建立技术影响力。</td><td>一个面向开发者场景的插件作品。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-3/cross-platform/pwa-local-app/">PWA 本地应用</a></td><td>把网页工具做成可安装应用，降低用户使用门槛。</td><td>一个可安装到手机或桌面的轻量应用。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-3/cross-platform/electron-voice-to-text/">Electron 桌面应用</a></td><td>做更完整的桌面生产力工具，适合重度工作流产品。</td><td>一个桌面端工具的最小可用版本。</td></tr></tbody></table><p>你的作品集建议分成三层：</p><ul><li>小工具：解决一个窄问题，发布快，适合吸引第一批关注。</li><li>小产品：有完整流程和基础数据，适合长期迭代。</li><li>旗舰项目：最能代表你能力的项目，用于个人主页、简历和社交平台置顶。</li></ul><h2 id="_6-视频制作、内容创作与视觉表达" tabindex="-1">6. 视频制作、内容创作与视觉表达 <a class="header-anchor" href="#_6-视频制作、内容创作与视觉表达" aria-label="Permalink to “6. 视频制作、内容创作与视觉表达”">​</a></h2><p>目标：让产品更容易被理解和传播。Easy-Vibe 不是专门的视频剪辑课程，所以这里推荐的是“产品视觉与内容表达”的相关课程；真正的视频剪辑技法还需要配合剪映、CapCut、Premiere 或其他外部课程。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/frontend/lovart-assets/">NanoBanana 素材生产</a></td><td>用 AI 生成海报、素材、品牌视觉和展示图，降低发布物料制作成本。</td><td>一张产品分享图和一组产品视觉素材。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/frontend/figma-mastergo/">Figma 与 MasterGo 入门</a></td><td>建立基础设计工具能力，用于封面、截图、落地页和产品结构设计。</td><td>一个产品封面或落地页视觉稿。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-2/frontend/multi-product-ui/">UI 设计规范与多产品界面</a></td><td>统一多个作品的视觉语言，避免每个产品都像临时拼出来的。</td><td>一份个人产品视觉规范：颜色、字体、按钮、截图风格。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-2/frontend/design-to-code/">设计原型到项目代码</a></td><td>把设计稿转成可交互页面，连接设计和开发。</td><td>一个从视觉稿落地到页面的完整案例。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/appendix/8-artificial-intelligence/image-generation.html">图像生成</a></td><td>理解 AI 图像生成的基本原理和适用边界。</td><td>可复用的封面、插图或宣传图提示词。</td></tr><tr><td>加分</td><td><a href="/easy-vibe/zh-cn/appendix/8-artificial-intelligence/multimodal-models.html">多模态模型</a></td><td>为图像理解、视频理解、语音和视觉 Agent 打基础。</td><td>一个未来多模态产品方向的能力清单。</td></tr></tbody></table><p>发布内容的最低配置：</p><ul><li>一张产品截图。</li><li>一张带标题的分享图。</li><li>一个 30 到 60 秒演示视频。</li><li>一篇短发布说明。</li><li>一个可以立刻点击试用的链接。</li></ul><h2 id="_7-游戏与互动体验开发" tabindex="-1">7. 游戏与互动体验开发 <a class="header-anchor" href="#_7-游戏与互动体验开发" aria-label="Permalink to “7. 游戏与互动体验开发”">​</a></h2><p>目标：如果你想做游戏、互动网站或可视化体验，先选轻量方向，不要一上来做大型游戏。Easy-Vibe 更适合帮你做“可演示、可传播的小互动作品”。</p><table tabindex="0"><thead><tr><th>优先级</th><th>课程</th><th>你能学到什么</th><th>学完应产出什么</th></tr></thead><tbody><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/ai-capabilities-through-games/">AI 时代，会说话就会编程</a></td><td>用小游戏理解 AI 编程从想法到运行的完整感觉。</td><td>一个能运行、能修改、能演示的小游戏。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.html">七款 AI 编程工具对比</a></td><td>通过贪吃蛇案例理解不同 AI 工具的生成差异和调试方式。</td><td>一份你偏好的游戏/互动开发工具选择。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/appendix/3-browser-and-frontend/graphics-animation.html">图形与动画</a></td><td>理解动画、Canvas、SVG、渲染和互动体验的基础。</td><td>一个小动画或 Canvas 互动 demo。</td></tr><tr><td>必学</td><td><a href="/easy-vibe/zh-cn/appendix/3-browser-and-frontend/javascript-deep-dive.html">JavaScript 深入</a></td><td>掌握事件、状态、异步和运行时行为，支撑游戏逻辑。</td><td>一个包含计分、状态更新和用户输入的小作品。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/appendix/3-browser-and-frontend/state-management.html">状态管理</a></td><td>管理复杂互动项目里的状态变化。</td><td>一套清晰的游戏状态或互动状态结构。</td></tr><tr><td>选学</td><td><a href="/easy-vibe/zh-cn/stage-3/cross-platform/pwa-local-app/">PWA 本地应用</a></td><td>把轻量小游戏或互动工具做成可安装应用。</td><td>一个可安装、可离线或半离线体验的小作品。</td></tr></tbody></table><p>建议先做三类小作品：</p><ul><li>一个 5 分钟能玩懂的小游戏。</li><li>一个能解释复杂概念的互动可视化。</li><li>一个带成就、积分、收藏或本地存档的轻量 PWA。</li></ul><h2 id="_8-你的-30-天发布计划" tabindex="-1">8. 你的 30 天发布计划 <a class="header-anchor" href="#_8-你的-30-天发布计划" aria-label="Permalink to “8. 你的 30 天发布计划”">​</a></h2><p>不要等“学完”再发布。用下面这个节奏做一个真实产品。</p><h3 id="第-1-周-选题与收敛" tabindex="-1">第 1 周：选题与收敛 <a class="header-anchor" href="#第-1-周-选题与收敛" aria-label="Permalink to “第 1 周：选题与收敛”">​</a></h3><ul><li>从现有半成品里选一个最适合发布的项目。</li><li>看 <a href="/easy-vibe/zh-cn/stage-1/finding-great-idea/">找到好点子</a>、<a href="/easy-vibe/zh-cn/stage-1/appendix-jobs-to-be-done/">Jobs to Be Done</a> 和 <a href="/easy-vibe/zh-cn/stage-1/appendix-mom-test/">The Mom Test</a>。</li><li>写出目标用户、核心场景、核心流程和不做清单。</li></ul><h3 id="第-2-周-补齐产品体验" tabindex="-1">第 2 周：补齐产品体验 <a class="header-anchor" href="#第-2-周-补齐产品体验" aria-label="Permalink to “第 2 周：补齐产品体验”">​</a></h3><ul><li>看 <a href="/easy-vibe/zh-cn/stage-1/building-prototype/">搭建产品原型</a>、<a href="/easy-vibe/zh-cn/stage-2/frontend/llm-skills-beautiful/">结合 Agent Skills 美化界面</a> 和 <a href="/easy-vibe/zh-cn/stage-2/frontend/modern-component-library/">现代组件库与界面升级</a>。</li><li>补齐首页、空状态、加载状态、错误状态和反馈入口。</li><li>找 3 个朋友或潜在用户试用，记录他们卡住的地方。</li></ul><h3 id="第-3-周-上线与基础数据" tabindex="-1">第 3 周：上线与基础数据 <a class="header-anchor" href="#第-3-周-上线与基础数据" aria-label="Permalink to “第 3 周：上线与基础数据”">​</a></h3><ul><li>看 <a href="/easy-vibe/zh-cn/stage-2/backend/zeabur-deployment/">网页应用部署全面指南</a>、<a href="/easy-vibe/zh-cn/stage-2/backend/git-workflow/">Git 与 GitHub 入门指南</a> 和 <a href="/easy-vibe/zh-cn/appendix/5-data/data-tracking.html">数据埋点</a>。</li><li>部署到公网。</li><li>加最简单的访问统计或事件记录。</li><li>写一篇发布说明。</li></ul><h3 id="第-4-周-传播与迭代" tabindex="-1">第 4 周：传播与迭代 <a class="header-anchor" href="#第-4-周-传播与迭代" aria-label="Permalink to “第 4 周：传播与迭代”">​</a></h3><ul><li>看 <a href="/easy-vibe/zh-cn/stage-3/personal-brand/personal-website-blog/">个人网页与学术博客</a>、<a href="/easy-vibe/zh-cn/appendix/9-engineering-excellence/technical-writing.html">技术写作</a> 和 <a href="/easy-vibe/zh-cn/appendix/5-data/data-analysis.html">数据分析</a>。</li><li>做一张分享图和一个短视频。</li><li>发到朋友圈、X、即刻、掘金、少数派、GitHub 或你常用的社区。</li><li>收集反馈，做一次小版本迭代。</li></ul><h2 id="_9-建议你现在立刻开始的-7-节" tabindex="-1">9. 建议你现在立刻开始的 7 节 <a class="header-anchor" href="#_9-建议你现在立刻开始的-7-节" aria-label="Permalink to “9. 建议你现在立刻开始的 7 节”">​</a></h2><p>如果你只想先启动，不想被庞大课程吓住，我建议按这个顺序：</p><ol><li><a href="/easy-vibe/zh-cn/stage-1/finding-great-idea/">找到好点子</a>：判断哪个半成品值得发布。</li><li><a href="/easy-vibe/zh-cn/stage-1/appendix-jobs-to-be-done/">用 Jobs to Be Done 找到用户真正想完成的事</a>：把功能想法变成用户任务。</li><li><a href="/easy-vibe/zh-cn/stage-1/building-prototype/">搭建产品原型</a>：把核心路径做清楚。</li><li><a href="/easy-vibe/zh-cn/stage-2/backend/zeabur-deployment/">网页应用部署全面指南</a>：获得公网链接。</li><li><a href="/easy-vibe/zh-cn/stage-2/frontend/llm-skills-beautiful/">结合 Agent Skills 美化界面</a>：解决“看起来不像正式产品”的问题。</li><li><a href="/easy-vibe/zh-cn/appendix/9-engineering-excellence/technical-writing.html">技术写作</a>：写清楚你的作品。</li><li><a href="/easy-vibe/zh-cn/stage-3/personal-brand/personal-website-blog/">如何构建个人网页与学术博客</a>：把多个作品沉淀成长期品牌资产。</li></ol><p>这七节刚好对应你的主要断点：筛选、定位、产品化、上线、打磨、讲述、被看见。</p>',66)])])}const g=a(r,[["render",l]]);export{p as __pageData,g as default};
